import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor matvec_forward(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Vectorized matrix-vector multiplication kernel.
// Computes C[m] = sum_k A[m, k] * B[k]  for a matrix A of shape (M, K)
// and a vector B of shape (K, 1). One CUDA block handles one row of A.
// Uses CuTe tensors for indexing, and CuTe's recast<> to reinterpret the
// contiguous K-dimension as float4 vectors for coalesced, wide loads.
template <typename T>
__global__ void matvec_kernel_vec4(
    const T* __restrict__ A,
    const T* __restrict__ B,
    T* __restrict__ C,
    int M, int K)
{
    int m = blockIdx.x;
    if (m >= M) return;

    int tid = threadIdx.x;
    int nthreads = blockDim.x;

    // CuTe views over the current row of A and over B (both length K, stride 1)
    Tensor gA = make_tensor(make_gmem_ptr(A + (int64_t)m * K), make_shape(K), make_stride(Int<1>{}));
    Tensor gB = make_tensor(make_gmem_ptr(B), make_shape(K), make_stride(Int<1>{}));

    // Reinterpret as float4 vectors (assumes K % 4 == 0)
    Tensor gA4 = recast<float4>(gA);
    Tensor gB4 = recast<float4>(gB);

    int K4 = size(gA4);

    float sum = 0.0f;
    for (int i = tid; i < K4; i += nthreads) {
        float4 a = gA4(i);
        float4 b = gB4(i);
        sum += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
    }

    // Warp-level reduction
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(0xffffffff, sum, offset);
    }

    __shared__ float warp_sums[32];
    int lane = tid & 31;
    int warp_id = tid >> 5;
    if (lane == 0) warp_sums[warp_id] = sum;
    __syncthreads();

    int num_warps = (nthreads + 31) / 32;
    if (warp_id == 0) {
        float val = (lane < num_warps) ? warp_sums[lane] : 0.0f;
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            val += __shfl_down_sync(0xffffffff, val, offset);
        }
        if (lane == 0) {
            C[m] = val;
        }
    }
}

// Fallback scalar kernel (used only if K is not divisible by 4)
template <typename T>
__global__ void matvec_kernel_scalar(
    const T* __restrict__ A,
    const T* __restrict__ B,
    T* __restrict__ C,
    int M, int K)
{
    int m = blockIdx.x;
    if (m >= M) return;

    int tid = threadIdx.x;
    int nthreads = blockDim.x;

    Tensor gA = make_tensor(make_gmem_ptr(A + (int64_t)m * K), make_shape(K), make_stride(Int<1>{}));
    Tensor gB = make_tensor(make_gmem_ptr(B), make_shape(K), make_stride(Int<1>{}));

    float sum = 0.0f;
    for (int i = tid; i < K; i += nthreads) {
        sum += gA(i) * gB(i);
    }

    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(0xffffffff, sum, offset);
    }

    __shared__ float warp_sums[32];
    int lane = tid & 31;
    int warp_id = tid >> 5;
    if (lane == 0) warp_sums[warp_id] = sum;
    __syncthreads();

    int num_warps = (nthreads + 31) / 32;
    if (warp_id == 0) {
        float val = (lane < num_warps) ? warp_sums[lane] : 0.0f;
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            val += __shfl_down_sync(0xffffffff, val, offset);
        }
        if (lane == 0) {
            C[m] = val;
        }
    }
}

torch::Tensor matvec_forward(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2, "A must be 2D (M, K)");
    TORCH_CHECK(B.dim() == 2, "B must be 2D (K, 1)");
    TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
                "Expect float32 tensors");

    int64_t M = A.size(0);
    int64_t K = A.size(1);
    TORCH_CHECK(B.size(0) == K, "B.size(0) must equal A.size(1)");
    TORCH_CHECK(B.size(1) == 1, "B must have shape (K, 1)");

    auto A_c = A.contiguous();
    auto B_c = B.contiguous();
    auto C = torch::empty({M, 1}, A.options());

    const float* ptrA = A_c.data_ptr<float>();
    const float* ptrB = B_c.data_ptr<float>();
    float* ptrC = C.data_ptr<float>();

    int threads = 256;
    dim3 grid((unsigned)M);
    dim3 block((unsigned)threads);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    if ((K % 4) == 0) {
        matvec_kernel_vec4<float><<<grid, block, 0, stream>>>(
            ptrA, ptrB, ptrC, (int)M, (int)K);
    } else {
        matvec_kernel_scalar<float><<<grid, block, 0, stream>>>(
            ptrA, ptrB, ptrC, (int)M, (int)K);
    }

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "matvec_kernel launch failed: ", cudaGetErrorString(err));

    return C;
}
"""

matvec_ext = load_inline(
    name="cute_matvec_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["matvec_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include/"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs matrix-vector multiplication (C = A * B)
    using a custom CuTe-based CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = matvec_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.matvec_forward(A.contiguous(), B.contiguous())

